/* The connected journey prototype uses an explicit illustrative network. */
const planner=MetroPlanner;
let draft={from:'maharagama',to:'ekala',time:384,speed:80,pickup:3,buffer:3,maxWalk:2000,allowRoad:true,stepFree:false};
let locationFix=null,locationState='',gpsNearest=null,locationRequest=0,lastResults=null,activePlan=null,planStep=0,sortPlan='fastest';
const clock=m=>{let h=Math.floor(m/60)%24;return (h%12||12)+':'+String(m%60).padStart(2,'0')+' '+(h>=12?'PM':'AM')};
const metres=d=>d>=1000?(d/1000).toFixed(1)+' km':d+' m';
const roadIcon=()=>`<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="M4 16V9h12l4 7v3H4zM7 9V5h8M4 14h14M9 9v7m6-7v7"/><circle cx="7" cy="19" r="2"/><circle cx="18" cy="19" r="2"/></svg>`;
const legIcon=l=>l.type==='bus'?ic('bus'):l.type==='road'?roadIcon():ic('walk');
const legLabel=l=>l.type==='bus'?l.label:l.type==='road'?'Tuk-tuk / taxi':'Walk';
const minuteInput=m=>String(Math.floor(m/60)%24).padStart(2,'0')+':'+String(m%60).padStart(2,'0');
function originOptions(value){return Object.entries(planner.places).map(([k,p])=>`<option value="${k}" ${k===value?'selected':''}>${p.name}</option>`).join('')}
planJourney=function(){modal('Plan your whole journey',`<p class="sub">From your starting point to the right bus, including connections.</p><div class="planner-demo"><b>Sample network</b> · Your Maharagama → Ekala example. Stops, service times and distances need operator verification.</div><form id="plannerForm" onsubmit="event.preventDefault();runPlanner()"><label for="plan-from">Starting point</label><div class="locationrow"><select id="plan-from">${originOptions(draft.from)}</select><button type="button" class="locatebutton" aria-label="Use my location" onclick="usePlannerLocation()">${ic('locate')}</button></div><button type="button" class="textbtn" onclick="usePlannerLocation()">Use my location</button><div id="locationStatus" role="status" aria-live="polite">${locationStatusHTML()}</div><label for="plan-to">Where would you like to go?</label><select id="plan-to">${originOptions(draft.to)}</select><div class="planner-fields"><div><label for="plan-time">Leave at · sample day</label><input type="time" id="plan-time" value="${minuteInput(draft.time)}" required></div><div><label for="plan-speed">Your walking pace</label><select id="plan-speed"><option value="45" ${draft.speed===45?'selected':''}>Very gentle · 2.7 km/h</option><option value="60" ${draft.speed===60?'selected':''}>Relaxed · 3.6 km/h</option><option value="80" ${draft.speed===80?'selected':''}>Usual · 4.8 km/h</option><option value="100" ${draft.speed===100?'selected':''}>Brisk · 6 km/h</option></select></div></div><details class="planner-preferences"><summary>Walking, pickup & accessibility preferences</summary><label for="plan-maxwalk">Maximum walk per leg</label><select id="plan-maxwalk">${[250,500,1000,2000].map(v=>`<option value="${v}" ${v===draft.maxWalk?'selected':''}>${metres(v)}</option>`).join('')}</select><label class="checkrow"><input id="plan-road" type="checkbox" ${draft.allowRoad?'checked':''}>Include tuk-tuk / taxi legs</label><label for="plan-pickup">Pickup allowance · estimate</label><select id="plan-pickup">${[3,5,10].map(v=>`<option value="${v}" ${v===draft.pickup?'selected':''}>${v} min</option>`).join('')}</select><label class="checkrow"><input id="plan-access" type="checkbox" ${draft.stepFree?'checked':''}>Only buses marked low-floor</label><p class="tiny">A low-floor bus does not verify stop access or wheelchair space. Tuk-tuk accessibility is unverified.</p></details><button class="primary full" type="submit" style="margin-top:21px">Find connections ${ic('arrow')}</button></form><p class="tiny" style="margin-top:16px">Calculations use the selected sample start, your pace, a ${draft.buffer}-minute boarding allowance, and sample timetables. They are not live travel advice.</p>`)};
function readDraft(){let time=$('#plan-time').value;if(!/^\d\d:\d\d$/.test(time))return false;let [h,m]=time.split(':').map(Number);draft={...draft,from:$('#plan-from').value,to:$('#plan-to').value,time:h*60+m,speed:Number($('#plan-speed').value),maxWalk:Number($('#plan-maxwalk').value),allowRoad:$('#plan-road').checked,pickup:Number($('#plan-pickup').value),stepFree:$('#plan-access').checked};return true}
function locationStatusHTML(){if(locationState==='loading')return '<div class="locationnotice">Finding your location…</div>';if(locationState==='found')return `<div class="locationnotice"><b>Location found · accuracy ±${Math.round(locationFix.accuracy)} m</b><br>Nearest <b>sample</b> stop: ${safe(gpsNearest.name)} · ${metres(gpsNearest.distance)} straight-line.<br><span>Walking-route distance and access time are unavailable. No catch estimate is made from this GPS fix.</span>${gpsNearest.distance<3000?`<button type="button" class="textbtn" onclick="useNearbySample()">Try this nearby sample starting point →</button>`:''}<button type="button" class="textbtn" onclick="locationFix=null;locationState='';gpsNearest=null;updateLocationStatus()">Clear location</button></div>`;return locationState?`<div class="locationnotice">${safe(locationState)}</div>`:''}
function updateLocationStatus(){let el=$('#locationStatus');if(el)el.innerHTML=locationStatusHTML()}
function usePlannerLocation(){if(!navigator.geolocation){locationState='Location is unavailable in this browser. Choose a starting point.';updateLocationStatus();return}locationState='loading';updateLocationStatus();const request=++locationRequest;navigator.geolocation.getCurrentPosition(pos=>{if(request!==locationRequest)return;locationFix={lat:pos.coords.latitude,lon:pos.coords.longitude,accuracy:pos.coords.accuracy};gpsNearest=planner.nearest(locationFix.lat,locationFix.lon)[0];locationState='found';updateLocationStatus()},error=>{if(request!==locationRequest)return;locationState=error.code===1?'Location permission was declined. You can still select a starting point.':error.code===3?'Location request timed out. Try again or select a starting point.':'Could not get your location. Select a starting point to continue.';updateLocationStatus()},{enableHighAccuracy:true,timeout:12000,maximumAge:30000})}
function useNearbySample(){if(!gpsNearest)return;let id=gpsNearest.id,key=id==='ap'?'apeksha':id.startsWith('kw')?'kaduwela':id.startsWith('kd')?'kadawatha':id==='bt'?'battaramulla':'ekala';$('#plan-from').value=key;toast('Sample starting point selected. This does not use a routed GPS walking distance.')}
locate=function(){usePlannerLocation()};
function runPlanner(){if(!readDraft())return;if(draft.from===draft.to){toast('Choose a different destination.');return}lastResults=planner.solve(draft);showPlanResults()}
function sortedJourneys(){let arr=[...(lastResults?.journeys||[])];if(sortPlan==='walking')arr.sort((a,b)=>a.walking-b.walking||a.end-b.end);else if(sortPlan==='changes')arr.sort((a,b)=>a.changes-b.changes||a.roadCount-b.roadCount||a.end-b.end);return arr}
function journeyStrip(j){return `<div class="legstrip">${j.legs.map(l=>`<span class="legchip ${l.type}">${legIcon(l)}<b>${l.type==='bus'?l.label:l.type==='road'?'Tuk-tuk':l.duration+' min'}</b></span>`).join('<span class="legarrow">›</span>')}</div>`}
function catchMessage(j){let c=j.firstCatch;if(c.missedEarlier)return `<span class="catchwarn">${ic('clock')}Too late for ${clock(c.nextBus)} ${c.accessMode==='walk'?'on foot':'with this access time'}. Take ${clock(c.boardingBus)} instead.</span>`;return `<span class="${j.minMargin<3?'catchwarn':'catchok'}">${ic(j.minMargin<3?'clock':'check')}${j.minMargin<3?(c.margin<3?'Tight first boarding':'Tight connection'):'Reachable in this sample'} · ${j.minMargin} min smallest margin after a ${j.options.buffer}-min boarding allowance.</span>`}
function journeyOption(j,i){let bus=j.legs.filter(l=>l.type==='bus'),transfer=j.legs.find(l=>l.kind==='transfer');return `<article class="connectioncard"><div class="between"><b class="connection-time">${clock(j.start)} → ${clock(j.end)}</b><span class="pill ${j.minMargin<3?'warn':''}">${j.duration} min</span></div><p class="tiny">${j.changes?j.changes+' change':'Direct bus'} · ${metres(j.walking)} walking${j.roadCount?' · '+j.roadCount+' tuk-tuk / taxi leg'+(j.roadCount>1?'s':''):''}</p>${journeyStrip(j)}<div class="catchbox">${catchMessage(j)}</div><div class="transfer-summary"><b>${j.changes?'Change at '+planner.nodes[bus[0].toId].area:'Board at '+planner.nodes[bus[0].fromId].short}</b>${transfer?`<span>${transfer.type==='walk'?metres(transfer.distance)+' walk · '+transfer.duration+' min':transfer.duration+' min tuk-tuk / taxi, including pickup'}<br>${j.transfer.description}</span>`:`<span>No bus change needed.</span>`}</div><button class="secondary full" onclick="inspectPlan('${j.id}')">View every step ${ic('arrow')}</button></article>`}
function showPlanResults(){let list=sortedJourneys();let walk=list.find(j=>j.roadCount===0),road=list.find(j=>j.roadCount>0);modal('Ways to get there',`<div class="plan-result-head"><span class="eyebrow">SAMPLE CONNECTIONS · ${clock(draft.time)}</span><h2>${planner.places[draft.from].name} → ${planner.places[draft.to].name}</h2><button class="textbtn" onclick="planJourney()">Edit search & pace</button></div><div class="planner-demo">Illustrative routing only. The feeder, transfer points, distances and schedules are unverified.</div>${!list.length?`<div class="card empty"><h2>${lastResults.reason==='accessibility'?'No verified low-floor connection':lastResults.reason==='unsupported'?'No connected sample route':'No option within your preferences'}</h2><p class="sub" style="margin:13px 0">${lastResults.reason==='accessibility'?'The feeder bus has no accessibility verification. We cannot mark this journey accessible.':lastResults.reason==='unsupported'?'The sample network currently supports journeys towards Ekala, with Maharagama feeder connections.':'Try a different departure time, a longer walk allowance, or allow a tuk-tuk leg. Sample services end in the evening.'}</p><button class="primary" onclick="planJourney()">Adjust search</button></div>`:`${walk&&road&&road.end<walk.end?`<div class="connection-insight"><b>A tuk-tuk could save ${walk.end-road.end} min in this sample.</b><span>Walking misses the earlier feeder. Pickup and road time are estimates, so check the timing below.</span></div>`:''}<div class="between" style="margin:17px 0"><b>${list.length} options</b><label class="sr-only" for="sortConnections">Sort connections</label><select id="sortConnections" class="compactselect" onchange="sortPlan=this.value;showPlanResults()"><option value="fastest" ${sortPlan==='fastest'?'selected':''}>Earliest arrival</option><option value="walking" ${sortPlan==='walking'?'selected':''}>Least walking</option><option value="changes" ${sortPlan==='changes'?'selected':''}>Fewest changes</option></select></div>${list.map(journeyOption).join('')}`}<p class="tiny" style="margin-top:20px">Pace: ${draft.speed} m/min · pickup: ${draft.pickup} min · boarding allowance: ${draft.buffer} min at each bus. Weather, traffic, queues and delays can change feasibility.</p>`)}
function findPlan(id){return lastResults.journeys.find(j=>j.id===id)}
function legTitle(l){if(l.type==='bus')return 'Take '+l.label+' towards '+l.headsign;if(l.type==='road')return 'Tuk-tuk / taxi to '+l.to;return 'Walk to '+l.to}
function detailStep(l,i,j,active){let current=active&&i===planStep,done=active&&i<planStep;let next=j.legs[i+1],before=j.legs[i-1];return `<section class="travelstep ${current?'current':done?'done':''}"><span class="stepdot" aria-hidden="true"></span><div class="step-heading"><span class="stepicon">${legIcon(l)}</span><b>${legTitle(l)}</b><span class="tiny">${clock(l.start)}<br>${clock(l.end)}</span></div><div class="stepbody"><p>${l.type==='bus'?`Board at <b>${l.from}</b>.<br>Get off at <b>${l.to}</b>.<br>${l.duration} min on board · ${l.wait} min at stop (includes ${l.buffer} min boarding allowance).`:l.type==='road'?`${metres(l.distance)} · about ${l.travel} min driving + ${l.pickup} min pickup allowance. No booking or driver availability is provided.`:`${metres(l.distance)} · about ${l.duration} min at your selected pace.${l.kind==='transfer'?'<br>'+j.transfer.description:''}`}</p>${l.type==='bus'&&next?.kind==='transfer'?`<div class="change-callout"><b>Get off here to change buses</b><span>${l.to} → ${next.to}</span><span>${next.type==='walk'?'Walk '+metres(next.distance)+' · '+next.duration+' min':'Tuk-tuk / taxi · '+next.duration+' min including pickup'}</span></div>`:''}${l.type==='bus'?`<p class="tiny">${l.accessible===true?'Low-floor bus · sample status':'Bus accessibility unverified'} · stop access & wheelchair space unverified</p>`:`<button class="textbtn" onclick="directionsFor('${j.id}',${i})">${ic('pin')}Directions to this stop →</button>`}${active&&current?`<button class="secondary full" onclick="completePlanStep()">${l.type==='bus'?'Simulate getting off':'Mark this sample leg complete'}</button>`:''}</div></section>`}
function planDetails(j,active=false){modal(active?'Your connected journey':'Every step of your journey',`<div class="journeyhead"><div class="between"><span>Sample journey</span><span class="pill">${j.changes} change${j.changes===1?'':'s'}</span></div><h2>${planner.places[j.from].name} → ${planner.places[j.to].name}</h2><p class="tiny">${clock(j.start)} – ${clock(j.end)} · ${j.duration} min</p>${journeyStrip(j)}</div><div class="catchbox">${catchMessage(j)}</div><p class="tiny" style="margin:16px 0 24px">Follow the boarding direction shown for each bus. Transfer positions are illustrative and must be confirmed before travel.</p>${j.legs.map((l,i)=>detailStep(l,i,j,active)).join('')}${j.warnings.length?`<div class="alert">${j.warnings.map(safe).join('<br>')}</div>`:''}<div class="access-note"><b>End-to-end accessibility is unverified.</b> Pavements, crossings, boarding sides, ramps and wheelchair spaces need verification. Tuk-tuk / taxi accessibility is also unverified.</div>${active?`<button class="textbtn full" onclick="activePlan=null;planStep=0;state.trip=false;closeModal();render()">Stop following this sample journey</button>`:`<button class="primary full" style="margin-top:20px" onclick="followPlan('${j.id}')">Follow this whole journey</button><button class="textbtn full" onclick="showPlanResults()">Compare other connections</button>`}<p class="tiny">This route uses the selected sample start, not a routed GPS location.</p>`)}
function inspectPlan(id){let j=findPlan(id);if(j)planDetails(j)}
function followPlan(id){activePlan=findPlan(id);planStep=0;following=true;state.trip=false;state.tab='explore';state.selected=0;closeModal();render();$('#panel').scrollTop=0;window.scrollTo({top:0,behavior:'smooth'});toast('All legs are now together on Home. This remains a sample journey.')}
function completePlanStep(){if(!activePlan)return;planStep++;if(planStep>=activePlan.legs.length){toast('Sample journey complete. No ticket or fare was issued.');activePlan=null;planStep=0;state.trip=false;closeModal();render();return}state.trip=activePlan.legs[planStep].type==='bus';render();planDetails(activePlan,true)}
function directionsFor(id,index){let j=activePlan?.id===id?activePlan:findPlan(id),l=j.legs[index];let destination=l.to.replace(/ · .*/,''),origin=l.from.replace(/ · .*/,'');let url='https://www.google.com/maps/dir/?api=1&origin='+encodeURIComponent(origin+', Sri Lanka')+'&destination='+encodeURIComponent(destination+', Sri Lanka')+'&travelmode='+(l.type==='walk'?'walking':'driving');modal('Directions to your next stop',`<h2 style="margin-bottom:15px">${l.to}</h2><p class="sub">${l.type==='walk'?'Walking':'Driving'} directions · ${metres(l.distance)} sample distance.</p><div class="access-note">Google Maps will use the selected place names to find directions. The sample stop positions and boarding side are unverified. Confirm the exact stop before travelling.</div><a class="primary full external-directions" target="_blank" rel="noopener noreferrer" href="${url}">Open directions in Google Maps ${ic('arrow')}</a><p class="tiny">Opens Google Maps and shares these place names. Your GPS coordinates are not included in this link. Maps may request its own location permission.</p><button class="textbtn full" onclick="planDetails(${activePlan?'activePlan':"findPlan('"+id+"')"},${!!activePlan})">Back to journey</button>`)}
const previousJourneyCard=journeyCard;journeyCard=function(){if(!activePlan){let text=previousJourneyCard();if(!state.trip&&!completed&&arrivalState()==='approaching'&&selected().mins<7){text=text.replace('Leave now for a comfortable walk to the stop.','4 min walking + 3 min boarding allowance. This arrival is too tight on foot.').replace(/<button class="primary" onclick="showQR\(\)">[\s\S]*?<\/button>/,'<button class="primary" onclick="checkDirectAccess()">Find a catchable bus</button>')}return text;}let j=activePlan,l=j.legs[planStep],nextBus=j.legs.slice(planStep).find(x=>x.type==='bus');return `<article class="journeycard"><div class="journeybody"><div class="between"><span class="triptitle">YOUR CONNECTED JOURNEY</span><span class="pill neutral">${j.changes} change</span></div><div class="journey-status" style="font-size:24px">${l.type==='bus'?'On '+l.label:l.type==='road'?'Take a tuk-tuk / taxi':'Walk to your next stop'}</div><p class="journey-sub">${l.type==='bus'?'Get off at '+l.to:l.to}</p>${journeyStrip(j)}<div class="journeyfacts"><div class="journeyfact">${l.type==='bus'?'GET OFF AT':'NEXT BUS'}<b>${l.type==='bus'?l.to:nextBus?.label+' · '+clock(nextBus?.start||j.end)}</b></div><div class="journeyfact">ARRIVE AT ${planner.places[j.to].name.toUpperCase()}<b>${clock(j.end)} · sample estimate</b></div></div><div class="catchbox">${catchMessage(j)}</div><button class="primary full" onclick="planDetails(activePlan,true)">View all legs & directions ${ic('arrow')}</button></div><div class="journeyfooter"><button onclick="planDetails(activePlan,true)">${legIcon(l)}Step ${planStep+1} of ${j.legs.length}</button><button onclick="planJourney()">Change journey</button></div></article>`};
const previousHome=home;home=function(){let html=previousHome();if(activePlan){html=html.replace(/<div class="directiontabs"[\s\S]*?<\/div>/,'');html=html.replace('Nearby departures','Your bus connections').replace('Your bus, right now','Your bus connections');html=html.replace(/<div class="mobilemap floatmap">[\s\S]*?<\/div><button[\s\S]*?<\/button><\/div>/,'');}return html};
const previousOnboardInfo=onboardInfo;onboardInfo=function(){if(activePlan)return nearbyCard();return previousOnboardInfo()};
const previousNearby=nearbyCard;nearbyCard=function(){if(!activePlan)return previousNearby();let bus=activePlan.legs.filter(l=>l.type==='bus');return `<div class="nearstop">${bus.map((l,i)=>`<div class="connection-bus"><span class="routebadge">${l.label}</span><span><b>${l.from}</b><small>Towards ${l.headsign} · board ${clock(l.start)}</small></span></div>`).join('')}<button class="textbtn full" onclick="planDetails(activePlan,true)">Where to get off & change buses →</button></div>`};
function checkDirectAccess(){draft={...draft,from:state.period==='morning'?'battaramulla':'ekala',to:state.period==='morning'?'ekala':'battaramulla',time:state.period==='morning'?384:1044};lastResults=planner.solve(draft);showPlanResults()}
const previousViewJourney=viewJourney;viewJourney=function(){if(activePlan)planDetails(activePlan,true);else{previousViewJourney();if(!state.trip&&arrivalState()==='approaching'&&selected().mins<7){$('.sheetcontent').insertAdjacentHTML('afterbegin','<div class="alert">This sample arrival is too tight on foot: 4 min walking + 3 min boarding allowance.<button class="textbtn full" onclick="checkDirectAccess()">Compare catchable buses →</button></div>')}}};
const previousRenderMap=renderMap;renderMap=function(){if(!activePlan){previousRenderMap();return}let j=activePlan;$('#maparea').innerHTML=`<div class="connected-map-head"><span class="eyebrow">YOUR WHOLE JOURNEY · SCHEMATIC</span><h2>${planner.places[j.from].name} → ${planner.places[j.to].name}</h2><p class="sub">Each walk, bus and transfer in one place.</p></div><div class="connected-schematic">${j.legs.map((l,i)=>`<button class="schemeleg ${i===planStep?'current':''}" onclick="planDetails(activePlan,true)"><span class="schemeicon">${legIcon(l)}</span><span><b>${legLabel(l)} · ${l.duration} min</b><small>${l.from} → ${l.to}</small></span><time>${clock(l.start)}</time></button>`).join('')}</div><div class="connected-map-bottom"><div class="access-note">Illustrative connections, not a geographical map. All boarding and transfer positions need verification.</div><button class="primary full" onclick="planDetails(activePlan,true)">Step-by-step journey & directions ${ic('arrow')}</button></div>`};
const previousViewMap=viewMap;viewMap=function(){if(activePlan)planDetails(activePlan,true);else previousViewMap()};
const previousRender=render;render=function(){previousRender();if(activePlan){let l=activePlan.legs[planStep];$('#rideDock').innerHTML=`<button class="dock-ticket" onclick="planDetails(activePlan,true)">${legIcon(l)}Next step</button><button class="dock-journey" onclick="planDetails(activePlan,true)"><span><strong>${planner.places[activePlan.from].name} → ${planner.places[activePlan.to].name}</strong><small>${legLabel(l)} · step ${planStep+1} of ${activePlan.legs.length}</small></span>${ic('arrow')}</button>`}};
const previousBusSelect=selectBus;selectBus=function(i){activePlan=null;planStep=0;state.trip=false;previousBusSelect(i)};
const previousPreview=applyPreview;applyPreview=function(v){activePlan=null;planStep=0;previousPreview(v)};
const previousSavedPanel=savedPanel;savedPanel=function(){if(!activePlan)return previousSavedPanel();let f=following,t=state.trip;following=false;state.trip=false;let html=previousSavedPanel();following=f;state.trip=t;let j=activePlan;return html.replace('</div>','</div><div class="card section"><span class="eyebrow">FOLLOWING · CONNECTED JOURNEY</span><h2 style="margin-top:12px">'+planner.places[j.from].name+' → '+planner.places[j.to].name+'</h2><p class="sub">'+j.changes+' change · '+j.duration+' min · sample</p><button class="primary full" style="margin-top:14px" onclick="planDetails(activePlan,true)">View all legs & directions</button></div>')};
const previousCode=showQR;showQR=function(){if(!activePlan)return previousCode();let bus=activePlan.legs.slice(planStep).find(l=>l.type==='bus');if(!bus){planDetails(activePlan,true);return}modal('Transit code · sample journey',`<div class="passes"><span class="pill neutral">DEMO · NOT A VALID TICKET</span><h2 style="margin:20px 0 10px">${bus.label} towards ${bus.headsign}</h2><p class="sub">Board at ${bus.from}. Get off at ${bus.to}.</p><div class="democode" style="margin-top:20px">${ticketIcon()}<b>PREVIEW ONLY</b></div><p class="tiny">A production code must be issued by the operator. No code, booking or payment is generated here.</p><button class="primary full" style="margin-top:20px" onclick="planDetails(activePlan,true)">Return to journey steps</button></div>`)};
const previousPeriod=period;period=function(p){activePlan=null;planStep=0;previousPeriod(p)};
render();
